const cfg = $('Config').first().json;
const TZ = Number(cfg.tz_offset_minutes) || 330;
const MAXB = Number(cfg.max_per_batch) || 10;
const dedupe = (String(cfg.dedupe_enabled) === 'true') || (cfg.dedupe_enabled === true);
const pad = (n) => String(n).padStart(2, '0');
const fmtDate = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
const now = new Date(Date.now() + TZ * 60000);
const today = fmtDate(now);
const tomorrow = fmtDate(new Date(now.getTime() + 86400000));
const yesterday = fmtDate(new Date(now.getTime() - 86400000));
const rows = $('Read Patient Log').all().map(i => i.json).filter(r => r && (r.appointment_id || r.record_id));
const opsRows = $('Read Ops Log').all().map(i => i.json).filter(r => r && r.appointment_id);
const done = {};
opsRows.forEach(r => { const k = String(r.appointment_id || '').trim() + '::' + String(r.action_type || '').trim(); done[k] = true; });
const wasDone = (id, type) => dedupe && !!done[String(id).trim() + '::' + type];
const issues = [];
const reminders = [];
const noshows = [];
const followups = [];
const todays = [];
let skipped = 0;
rows.forEach(r => {
  const slot = String(r.appointment_slot || '').trim();
  const status = String(r.status || '').toLowerCase().trim();
  const email = String(r.patient_email || '').trim();
  const name = String(r.patient_name || 'Patient');
  const id = String(r.appointment_id || r.record_id || '');
  const item = { appointment_id: id, name: name, email: email, phone: String(r.patient_phone || ''), doctor: String(r.doctor || 'the doctor'), specialty: String(r.specialty || 'General Medicine'), slot: slot, symptoms: String(r.symptoms || 'not recorded'), urgency: String(r.urgency || 'routine'), status: status };
  const slotDate = slot.slice(0, 10);
  const isDate = slotDate.length === 10 && slotDate.indexOf('-') === 4;
  if (!isDate) { return; }
  if (slotDate === today) { todays.push(item); }
  if (slotDate === tomorrow && (status === 'booked' || status === 'escalated')) { if (wasDone(id, 'reminder')) { skipped += 1; } else { reminders.push(item); } }
  if (slotDate < today && status === 'booked') { if (wasDone(id, 'noshow')) { skipped += 1; } else { noshows.push(item); } }
  if (slotDate === yesterday && status === 'completed') { if (wasDone(id, 'followup')) { skipped += 1; } else { followups.push(item); } }
});
const withEmail = (a) => a.filter(x => { if (!x.email) { issues.push('No email on record for ' + x.name); return false; } return true; });
const remindersS = withEmail(reminders).slice(0, MAXB);
const noshowsS = withEmail(noshows).slice(0, MAXB);
const followupsS = withEmail(followups).slice(0, MAXB);
const lineOf = (x) => x.appointment_id + ' | ' + x.name + ' | ' + x.slot + ' | ' + x.doctor + ' (' + x.specialty + ') | reported: ' + x.symptoms;
let remLines = '';
remindersS.forEach(x => { remLines += lineOf(x) + '\n'; });
let nsLines = '';
noshowsS.forEach(x => { nsLines += lineOf(x) + '\n'; });
let fuLines = '';
followupsS.forEach(x => { fuLines += lineOf(x) + '\n'; });
let todayLines = '';
todays.forEach(x => { todayLines += x.slot + ' | ' + x.name + ' | ' + x.doctor + ' | ' + x.urgency + '\n'; });
const byDoc = {};
todays.forEach(x => { byDoc[x.doctor] = (byDoc[x.doctor] || 0) + 1; });
let docLines = '';
Object.keys(byDoc).forEach(k => { docLines += k + ': ' + byDoc[k] + '\n'; });
const urgentToday = todays.filter(x => x.urgency === 'emergency' || x.urgency === 'urgent').length;
const totalActions = remindersS.length + noshowsS.length + followupsS.length;
return [{ json: {
  run_date: today, tomorrow_date: tomorrow, yesterday_date: yesterday,
  clinic_name: cfg.clinic_name, clinic_phone: cfg.clinic_phone, clinic_address: cfg.clinic_address,
  owner_email: cfg.owner_email, review_link: cfg.review_link,
  reminders: remindersS, noshows: noshowsS, followups: followupsS, todays: todays,
  reminder_count: remindersS.length, noshow_count: noshowsS.length, followup_count: followupsS.length,
  today_count: todays.length, urgent_today: urgentToday, total_actions: totalActions,
  skipped_count: skipped, dedupe_enabled: dedupe, total_records: rows.length, ops_log_rows: opsRows.length,
  reminder_lines: remLines || 'none', noshow_lines: nsLines || 'none', followup_lines: fuLines || 'none',
  today_lines: todayLines || 'none', doctor_load_lines: docLines || 'none',
  data_issues: issues.slice(0, 10), data_issue_count: issues.length
} }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); try { return JSON.parse(t); } catch (err) { return null; } };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $('Ops Engine').first().json;
const parsed = parseJson(textOf($input.first().json)) || {};
const msgs = Array.isArray(parsed.messages) ? parsed.messages : [];
const all = [];
(d.reminders || []).forEach(x => { all.push({ item: x, type: 'reminder' }); });
(d.noshows || []).forEach(x => { all.push({ item: x, type: 'noshow' }); });
(d.followups || []).forEach(x => { all.push({ item: x, type: 'followup' }); });
if (all.length === 0) { return []; }
const pad = (n) => String(n).padStart(2, '0');
const nowIst = new Date(Date.now() + 330 * 60000);
const stamp = nowIst.getUTCFullYear() + pad(nowIst.getUTCMonth() + 1) + pad(nowIst.getUTCDate()) + pad(nowIst.getUTCHours()) + pad(nowIst.getUTCMinutes());
const sentAt = d.run_date + ' ' + pad(nowIst.getUTCHours()) + ':' + pad(nowIst.getUTCMinutes());
const SLATE = '#0F2A3D', TEAL = '#0E7C7B', CREAM = '#F4F5F0', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#666666', AMBER = '#E67E22';
const labelOf = (t) => t === 'reminder' ? 'APPOINTMENT REMINDER' : (t === 'noshow' ? 'WE MISSED YOU' : 'HOW ARE YOU FEELING');
const accentOf = (t) => t === 'noshow' ? AMBER : TEAL;
const out = [];
all.forEach((entry, idx) => {
  const x = entry.item;
  const m = msgs.find(q => String(q.appointment_id || '').trim() === x.appointment_id && String(q.type || '').trim() === entry.type) || msgs.find(q => String(q.appointment_id || '').trim() === x.appointment_id) || {};
  const subject = m.subject || (entry.type === 'reminder' ? ('Reminder: your appointment on ' + x.slot) : (entry.type === 'noshow' ? 'We missed you at the clinic' : 'Checking in after your visit'));
  const lines = Array.isArray(m.lines) && m.lines.length ? m.lines : ['Our team will contact you shortly regarding your appointment.'];
  let bodyHtml = '';
  lines.forEach(l => { bodyHtml += '<div style="font-size:15px;color:' + INK + ';line-height:1.6;margin-bottom:9px;">' + esc(l) + '</div>'; });
  const accent = accentOf(entry.type);
  const reviewBtn = entry.type === 'followup' && d.review_link ? ('<tr><td style="padding:4px 26px 16px 26px;"><a href="' + esc(d.review_link) + '" style="display:inline-block;background:' + TEAL + ';color:#FFFFFF;font-size:14px;font-weight:bold;text-decoration:none;padding:11px 20px;border-radius:6px;">Leave us a review</a></td></tr>') : '';
  const detailRow = entry.type === 'followup' ? '' : ('<tr><td style="padding:8px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E4E4DC;border-radius:8px;border-left:4px solid ' + accent + ';">' +
    '<tr><td style="padding:12px 14px;font-size:12px;color:' + GREY + ';">Doctor</td><td align="right" style="padding:12px 14px;font-size:14px;font-weight:bold;color:' + SLATE + ';">' + esc(x.doctor) + '</td></tr>' +
    '<tr><td style="padding:12px 14px;font-size:12px;color:' + GREY + ';border-top:1px solid #E4E4DC;">Department</td><td align="right" style="padding:12px 14px;font-size:14px;color:' + SLATE + ';border-top:1px solid #E4E4DC;">' + esc(x.specialty) + '</td></tr>' +
    '<tr><td style="padding:12px 14px;font-size:12px;color:' + GREY + ';border-top:1px solid #E4E4DC;">Appointment</td><td align="right" style="padding:12px 14px;font-size:14px;font-weight:bold;color:' + accent + ';border-top:1px solid #E4E4DC;">' + esc(x.slot) + '</td></tr>' +
    '</table></td></tr>');
  const html = '<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;">' +
    '<table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
    '<tr><td style="background:' + SLATE + ';padding:22px 26px;"><div style="color:#7FD1CE;font-size:11px;font-weight:bold;letter-spacing:3px;">' + labelOf(entry.type) + '</div>' +
    '<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:22px;font-weight:bold;margin-top:6px;">' + esc(d.clinic_name) + '</div></td></tr>' +
    '<tr><td style="padding:22px 26px 6px 26px;"><div style="font-size:16px;font-weight:bold;color:' + INK + ';margin-bottom:12px;">Namaste ' + esc(x.name) + ',</div>' + bodyHtml + '</td></tr>' +
    detailRow + reviewBtn +
    '<tr><td style="padding:14px 26px 20px 26px;"><div style="font-size:13px;color:' + GREY + ';">' + esc(d.clinic_address) + '<br>Call us: ' + esc(d.clinic_phone) + '</div></td></tr>' +
    '<tr><td style="background:' + CREAM + ';padding:12px 26px;"><div style="font-size:11px;color:' + GREY + ';line-height:1.45;">This message is about your appointment only. It is not medical advice or a diagnosis. In an emergency please call ' + esc(d.clinic_phone) + ' or go to the nearest emergency room.</div></td></tr>' +
    '</table></div>';
  out.push({ json: { log_id: 'OP' + stamp + '-' + pad(idx + 1), run_date: d.run_date, sent_at: sentAt, to: x.email, subject: subject, html: html, action_type: entry.type, appointment_id: x.appointment_id, patient_name: x.name, ai_ok: !!m.subject } });
});
return out;

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); try { return JSON.parse(t); } catch (err) { return null; } };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $('Ops Engine').first().json;
const b = parseJson(textOf($input.first().json)) || {};
const aiOk = !!b.headline;
const headline = b.headline || (d.today_count + ' appointments scheduled today');
const summary = b.summary || 'Your clinic ops summary is ready.';
const actions = Array.isArray(b.actions) ? b.actions : [];
const riskNote = b.risk_note || '';
const SLATE = '#0F2A3D', TEAL = '#0E7C7B', CREAM = '#F4F5F0', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#666666', RED = '#C0392B', AMBER = '#E67E22';
const issues = Array.isArray(d.data_issues) ? d.data_issues.slice(0) : [];
if (!aiOk) { issues.push('Ops brief AI was unavailable, showing computed figures only'); }
if (d.dedupe_enabled && d.ops_log_rows === 0 && d.total_actions > 0) { issues.push('Communication log is empty, duplicate protection could not verify past sends'); }
let bannerHtml = '';
if (issues.length) { bannerHtml = '<tr><td style="padding:12px 26px 0 26px;"><div style="background:#FBE9E7;border-left:4px solid ' + RED + ';border-radius:6px;padding:11px 13px;font-size:12.5px;color:#7A1F14;"><strong>Heads up.</strong> ' + esc(issues.slice(0, 3).join('; ')) + '</div></td></tr>'; }
let todayHtml = '';
(d.todays || []).forEach(x => {
  const uc = x.urgency === 'emergency' ? RED : (x.urgency === 'urgent' ? AMBER : TEAL);
  todayHtml += '<tr><td style="padding:10px 12px;border-bottom:1px solid #E4E4DC;font-size:13px;color:' + INK + ';"><strong>' + esc(x.name) + '</strong><br><span style="color:' + GREY + ';font-size:11px;">' + esc(x.specialty) + ' &middot; ' + esc(x.doctor) + '</span></td>' +
    '<td align="center" style="padding:10px 12px;border-bottom:1px solid #E4E4DC;font-size:13px;color:' + INK + ';">' + esc(String(x.slot).slice(11)) + '</td>' +
    '<td align="right" style="padding:10px 12px;border-bottom:1px solid #E4E4DC;font-size:12px;font-weight:bold;color:' + uc + ';">' + esc(String(x.urgency).toUpperCase()) + '</td></tr>';
});
let nsHtml = '';
(d.noshows || []).forEach(x => {
  nsHtml += '<tr><td style="padding:9px 12px;border-bottom:1px solid #E4E4DC;font-size:13px;color:' + INK + ';"><strong>' + esc(x.name) + '</strong> <span style="color:' + GREY + ';font-size:11px;">' + esc(x.phone) + '</span></td>' +
    '<td align="right" style="padding:9px 12px;border-bottom:1px solid #E4E4DC;font-size:12px;color:' + GREY + ';">missed ' + esc(String(x.slot).slice(0, 10)) + '</td></tr>';
});
let actionsHtml = '';
actions.forEach(a => { actionsHtml += '<li style="margin-bottom:6px;">' + esc(a) + '</li>'; });
const metric = (val, label, bg, fg, sub) => '<td align="center" style="background:' + bg + ';border-radius:6px;padding:14px 6px;"><div style="color:' + fg + ';font-family:Georgia,serif;font-size:24px;font-weight:bold;">' + esc(val) + '</div><div style="color:' + sub + ';font-size:10.5px;">' + esc(label) + '</div></td>';
const dedupeLine = d.dedupe_enabled ? (d.skipped_count + ' message(s) skipped, already sent earlier &middot; ' + d.ops_log_rows + ' in the communication log') : 'duplicate protection is switched off';
const html = '<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;">' +
'<table width="100%" cellpadding="0" cellspacing="0" style="max-width:660px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
'<tr><td style="background:' + SLATE + ';padding:24px 26px;"><div style="color:#7FD1CE;font-size:11px;font-weight:bold;letter-spacing:3px;">DAILY CLINIC OPS BRIEF</div>' +
'<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:25px;font-weight:bold;margin-top:7px;">' + esc(d.clinic_name) + '</div>' +
'<div style="color:#9AB2C0;font-size:13px;margin-top:5px;">' + esc(d.run_date) + ' &middot; ' + esc(d.total_records) + ' patient records on file</div></td></tr>' + bannerHtml +
'<tr><td style="padding:18px 26px 4px 26px;"><table width="100%" cellpadding="0" cellspacing="0"><tr>' +
metric(d.today_count, 'today', SLATE, '#7FD1CE', '#9AB2C0') + '<td width="8"></td>' +
metric(d.reminder_count, 'reminders sent', CREAM, TEAL, GREY) + '<td width="8"></td>' +
metric(d.noshow_count, 'to rebook', CREAM, AMBER, GREY) + '<td width="8"></td>' +
metric(d.followup_count, 'follow ups', CREAM, TEAL, GREY) +
'</tr></table>' +
'<div style="font-size:11.5px;color:' + GREY + ';margin-top:8px;text-align:center;">' + dedupeLine + '</div></td></tr>' +
'<tr><td style="padding:12px 26px 4px 26px;"><div style="background:' + CREAM + ';border-radius:8px;padding:16px 18px;border-left:4px solid ' + TEAL + ';">' +
'<div style="font-family:Georgia,serif;font-size:17px;font-weight:bold;color:' + SLATE + ';line-height:1.35;">' + esc(headline) + '</div>' +
'<div style="font-size:14px;color:' + INK + ';line-height:1.55;margin-top:8px;">' + esc(summary) + '</div></div></td></tr>' +
(todayHtml ? ('<tr><td style="padding:18px 26px 4px 26px;"><div style="font-family:Georgia,serif;font-size:15px;font-weight:bold;color:' + SLATE + ';margin-bottom:8px;">Today at the clinic</div><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E4E4DC;border-radius:8px;">' + todayHtml + '</table></td></tr>') : '') +
(nsHtml ? ('<tr><td style="padding:18px 26px 4px 26px;"><div style="font-family:Georgia,serif;font-size:15px;font-weight:bold;color:' + SLATE + ';margin-bottom:8px;">Missed, rebooking message sent</div><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E4E4DC;border-radius:8px;">' + nsHtml + '</table></td></tr>') : '') +
(actionsHtml ? ('<tr><td style="padding:18px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="background:' + SLATE + ';border-radius:8px;"><tr><td style="padding:18px 20px;"><div style="color:#7FD1CE;font-family:Georgia,serif;font-size:16px;font-weight:bold;margin-bottom:9px;">Do this today</div><ul style="color:#E4ECF0;font-size:14px;line-height:1.5;margin:0;padding-left:20px;">' + actionsHtml + '</ul>' + (riskNote ? ('<div style="color:#9AB2C0;font-size:12px;margin-top:12px;font-style:italic;">Watch out: ' + esc(riskNote) + '</div>') : '') + '</td></tr></table></td></tr>') : '') +
'<tr><td style="background:' + SLATE + ';padding:12px 26px;"><div style="color:#9AB2C0;font-size:11px;">' + esc(d.clinic_name) + ' &middot; Clinic Daily Ops Engine &middot; Powered by Haus of Intelligence</div></td></tr>' +
'</table></div>';
return [{ json: { digest_html: html, ops_ok: aiOk, today_count: d.today_count, total_actions: d.total_actions } }];
